/**
 * Election reference data and INEC candidate lists, served as static JSON from
 * /data/elections/<year>/ (generated by server/scripts/export_client_data.py from INEC's
 * official final lists). Works offline once cached by the service worker.
 */
const BASE = "/data/elections/2027";
const memo = new Map();

async function getJSON(path) {
  if (!memo.has(path)) {
    memo.set(path, fetch(`${BASE}/${path}`).then((r) => {
      if (!r.ok) throw new Error(`Election data unavailable (${r.status})`);
      return r.json();
    }).catch((e) => { memo.delete(path); throw e; }));
  }
  return memo.get(path);
}

export const ELECTION_IDS = ["presidential", "senate", "house_of_reps", "governorship", "state_assembly"];
export const HAS_CONSTITUENCY = new Set(["senate", "house_of_reps", "state_assembly"]);

export const getReference = () => getJSON("reference.json");
export const getIndex = () => getJSON("index.json");

/** States that hold this election in 2027 (governorship excludes the 8 off-cycle states). */
export async function statesFor(election) {
  const [ref, index] = await Promise.all([getReference(), getIndex()]);
  const available = new Set(Object.keys(index.elections[election]?.states || {}));
  return ref.states.filter((s) => (election === "presidential" ? true : available.has(s.slug)));
}

export async function constituenciesFor(election, state) {
  const index = await getIndex();
  return index.elections[election]?.states?.[state]?.constituencies || [];
}

/**
 * Official ballot entries for one contest, in INEC's list order.
 * @returns {{entries: object[], source: {url, sha256, fetched_at}} | null}
 */
export async function ballotFor(election, state, constituency) {
  if (election === "presidential") {
    const d = await getJSON("presidential.json");
    return { entries: d.states.nigeria, source: d.sources.nigeria };
  }
  if (election === "governorship") {
    const d = await getJSON("governorship.json");
    return d.states[state] ? { entries: d.states[state], source: d.sources[state] } : null;
  }
  if (!state) return null;
  const d = await getJSON(`${election}/${state}.json`);
  const entries = constituency ? d.entries.filter((e) => e.constituency === constituency) : d.entries;
  return { entries, source: d.source };
}

/** Title-case an INEC upper-case name for display ("TINUBU BOLA AHMED" -> "Tinubu Bola Ahmed"). */
export function displayName(name) {
  if (!name) return null;
  return name.toLowerCase().replace(/(^|[\s\-'/])(\p{L})/gu, (_, sep, ch) => sep + ch.toUpperCase());
}

export function daysUntil(isoDate, now = new Date()) {
  const d = new Date(`${isoDate}T00:00:00+01:00`); // dates are in Nigerian time (WAT, UTC+1)
  return Math.ceil((d - now) / 86_400_000);
}
